def run(cmd, input_data=b"", timeout=3):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    # set window size
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    out = b""
    import time
    start = time.time()
    while True:
