                    r,_,_ = select.select([fd],[],[],0.1)
                    if fd in r:
                        try:
                            d = os.read(fd, 4096)
                            if not d: break
                            out += d
                        except OSError:
                            break
                    else:
                        break
                break
        except ChildProcessError:
            break
    try:
        os.kill(pid, 9)
        os.waitpid(pid, 0)
    except:
        pass
    return out

