        "Options:\n"
        "  +<number>       Select line <number> in the first view\n"
        "  -v, --version   Show version and exit\n"
        "  -h, --help      Show help message and exit\n"
        "  -C <path>       Start in <path>\n",
        stdout);
    fflush(stdout);
