/*
 * Minimal tig reimplementation focused on CLI interface behavior.
 *
 * Observed behaviors:
 *  -h / --help     => print help text to stdout, exit 0
 *  -v / --version  => print version text to stdout, exit 0
 *  -C <path>       => chdir to <path>; on failure print error and exit 1
 *  --              => stop option parsing
 *  subcommands: log, show, reflog, blame, grep, refs, stash, status, diff
 *  +<N>            => requested line number (N must be integer)
 *  other positional args are revs/paths; passed to `git rev-parse` for
 *    validation.  On rev-parse failure: "tig: No revisions match the
 *    given arguments." exit 1.
 *  Otherwise: "tig: Failed to open tty for input" exit 1 (since the UI
 *  cannot be started without a terminal in this environment).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <ctype.h>
#include <fcntl.h>
#include <errno.h>

static void print_help(void)
{
    fputs(
        "tig 2.6.0-g87c9c25 \n"
        "\n"
        "Usage: tig        [options] [revs] [--] [paths]\n"
        "   or: tig log    [options] [revs] [--] [paths]\n"
        "   or: tig show   [options] [revs] [--] [paths]\n"
        "   or: tig reflog [options] [revs]\n"
        "   or: tig blame  [options] [rev] [--] path\n"
        "   or: tig grep   [options] [pattern]\n"
        "   or: tig refs   [options]\n"
        "   or: tig stash  [options]\n"
        "   or: tig status\n"
        "   or: tig <      [git command output]\n"
        "\n"
        "Options:\n"
        "  +<number>       Select line <number> in the first view\n"
        "  -v, --version   Show version and exit\n"
        "  -h, --help      Show help message and exit\n"
        "  -C <path>       Start in <path>\n",
        stdout);
    fflush(stdout);
}

static void print_version(void)
{
    puts("tig version 2.6.0-g87c9c25");
    puts("ncursesw version 6.3.20211021");
    fflush(stdout);
}

static int is_subcommand(const char *s)
{
    static const char *subs[] = {
        "log", "show", "reflog", "blame", "grep",
        "refs", "stash", "status", "diff", NULL
    };
    for (int i = 0; subs[i]; i++)
        if (strcmp(s, subs[i]) == 0)
            return 1;
    return 0;
}

/* Returns 1 if the string looks like "+<digits>" (with at least one digit). */
static int is_plus_number(const char *s)
{
    if (s[0] != '+' || s[1] == '\0')
        return 0;
    for (const char *p = s + 1; *p; p++)
        if (!isdigit((unsigned char)*p))
            return 0;
    return 1;
}

/*
 * Invoke `git rev-parse <args...>` silently.  Returns 0 on success,
 * non-zero if git exits with error.
 */
static int git_rev_parse_ok(char **args, int n)
{
    pid_t pid = fork();
    if (pid < 0)
        return -1;

    if (pid == 0) {
        int devnull = open("/dev/null", O_WRONLY);
        if (devnull >= 0) {
            dup2(devnull, 1);
            dup2(devnull, 2);
            if (devnull > 2) close(devnull);
        }
        char **av = calloc((size_t)n + 3, sizeof(char *));
        if (!av) _exit(127);
        int k = 0;
        av[k++] = (char *)"git";
        av[k++] = (char *)"rev-parse";
        for (int i = 0; i < n; i++)
            av[k++] = args[i];
        av[k] = NULL;
        execvp("git", av);
        _exit(127);
    }

    int status = 0;
    if (waitpid(pid, &status, 0) < 0)
        return -1;
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0)
        return 0;
    return 1;
}

int main(int argc, char **argv)
{
    int options_mode = 1;          /* -C only valid while true */
    int double_dash = 0;
    int subcmd_seen = 0;
    int n_revs = 0;
    char **rev_args = calloc((size_t)argc + 1, sizeof(char *));
    if (!rev_args) {
        fprintf(stderr, "tig: out of memory\n");
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        char *a = argv[i];

        if (!double_dash) {
            if (strcmp(a, "--") == 0) {
                double_dash = 1;
                options_mode = 0;
                continue;
            }
            if (strcmp(a, "-h") == 0 || strcmp(a, "--help") == 0) {
                print_help();
                free(rev_args);
                return 0;
            }
            if (strcmp(a, "-v") == 0 || strcmp(a, "--version") == 0) {
                print_version();
                free(rev_args);
                return 0;
            }
            if (options_mode && strcmp(a, "-C") == 0) {
                if (i + 1 < argc) {
                    if (chdir(argv[i + 1]) != 0) {
                        fprintf(stderr,
                                "tig: Failed to change directory to %s\n",
                                argv[i + 1]);
                        free(rev_args);
                        return 1;
                    }
                    i++;
                }
                continue;
            }

            /* Non-option encountered: leave options mode. */
            options_mode = 0;

            if (!subcmd_seen && is_subcommand(a)) {
                subcmd_seen = 1;
                continue;
            }

            if (is_plus_number(a)) {
                /* Line-number directive; consume without passing to git. */
                continue;
            }
        }

        rev_args[n_revs++] = a;
    }

    if (n_revs > 0) {
        if (git_rev_parse_ok(rev_args, n_revs) != 0) {
            fprintf(stderr,
                    "tig: No revisions match the given arguments.\n");
            free(rev_args);
            return 1;
        }
    }

    fprintf(stderr, "tig: Failed to open tty for input\n");
    free(rev_args);
    return 1;
}
